from copy import deepcopy
from difflib import SequenceMatcher
import math


class MemoryCatalog:
    def __init__(self, entries):
        if isinstance(entries, (str, bytes)):
            raise TypeError("entries must be an iterable")
        try:
            values = list(entries)
        except TypeError as exc:
            raise TypeError("entries must be iterable") from exc
        seen = set()
        required = {"id", "title", "category", "enabled", "rank"}
        for entry in values:
            if not isinstance(entry, dict):
                raise TypeError("entries must be dictionaries")
            if set(entry) != required:
                raise ValueError("invalid entry fields")
            if not isinstance(entry["id"], str) or not entry["id"]:
                raise ValueError("id must be a non-empty string")
            if entry["id"] in seen:
                raise ValueError("duplicate id")
            seen.add(entry["id"])
            if not isinstance(entry["title"], str) or not isinstance(entry["category"], str):
                raise TypeError("title and category must be strings")
            if not isinstance(entry["enabled"], bool):
                raise TypeError("enabled must be boolean")
            rank = entry["rank"]
            if isinstance(rank, bool) or not isinstance(rank, (int, float)):
                raise TypeError("rank must be numeric")
            if not math.isfinite(rank):
                raise ValueError("rank must be finite")
        self._entries = deepcopy(values)

    def search(self, term, category=None, enabled=None, offset=0, limit=20):
        if not isinstance(term, str):
            raise TypeError("term must be a string")
        if category is not None and not isinstance(category, str):
            raise TypeError("category must be a string or None")
        if enabled is not None and not isinstance(enabled, bool):
            raise TypeError("enabled must be boolean or None")
        for name, value in (("offset", offset), ("limit", limit)):
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError(f"{name} must be an integer")
            if value < 0:
                raise ValueError(f"{name} must be non-negative")
        needle = term.casefold()
        matches = []
        for entry in self._entries:
            title = entry["title"].casefold()
            text_match = not needle or needle in title or SequenceMatcher(None, needle, title).ratio() >= 0.6
            if text_match and (category is None or entry["category"] == category) and (enabled is None or entry["enabled"] is enabled):
                matches.append(entry)
        matches.sort(key=lambda entry: (-entry["rank"], entry["title"].casefold(), entry["id"]))
        return deepcopy(matches[offset:offset + limit])
